/*
 * vizcn motion — optional pure-CSS entrance/interaction kit (vc-* classes).
 * Forms render fine without it; with it they animate in. Ships via the
 * theme item's css field (plain @keyframes — Tailwind v3 and v4 safe).
 * Respects prefers-reduced-motion. Scroll-driven reveals use
 * animation-timeline: view() where the browser supports it.
 */
@keyframes vc-in {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
.vc-pop { animation: vc-in 0.55s cubic-bezier(0.2, 0.7, 0.3, 1) both; }
@keyframes vc-blink {
  0%, 55% { opacity: 1; }
  56%, 100% { opacity: 0; }
}
.vc-blink { animation: vc-blink 1.1s steps(1) infinite; }
.vc-lift { transition: transform 0.18s ease, border-color 0.18s ease, background-color 0.18s ease, color 0.18s ease; }
.vc-lift:hover { transform: translateY(-2px); }
.vc-focus > * { transition: opacity 0.15s ease; }
.vc-focus:hover > :not(:hover) { opacity: 0.35; }
@supports (animation-timeline: view()) {
  .vc-reveal { animation: vc-in 0.6s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 32%; }
  .vc-grow-x { transform-box: fill-box; transform-origin: left center; animation: vc-sx 0.8s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 42%; }
  .vc-grow-y { transform-box: fill-box; transform-origin: center bottom; animation: vc-sy 0.8s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 42%; }
  .vc-grow-y-down { transform-box: fill-box; transform-origin: center top; animation: vc-sy 0.8s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 42%; }
  .vc-grow-x-rev { transform-box: fill-box; transform-origin: right center; animation: vc-sx 0.8s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 42%; }
  .vc-mark { transform-box: fill-box; transform-origin: center; animation: vc-mk 0.6s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 40%; }
  .vc-draw { stroke-dasharray: 1; animation: vc-dr 0.9s cubic-bezier(0.2, 0.7, 0.3, 1) both; animation-timeline: view(); animation-range: entry 0% entry 50%; }
}
@keyframes vc-sx { from { transform: scaleX(0); } }
@keyframes vc-sy { from { transform: scaleY(0); } }
@keyframes vc-mk { from { opacity: 0; transform: scale(0.3); } }
@keyframes vc-dr { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce) {
  .vc-pop, .vc-reveal, .vc-blink, .vc-grow-x, .vc-grow-y, .vc-mark, .vc-grow-y-down, .vc-grow-x-rev { animation: none; }
  .vc-draw { animation: none; stroke-dasharray: none; stroke-dashoffset: 0; }
  .vc-lift, .vc-lift:hover { transition: none; transform: none; }
  .vc-focus > * { transition: none; }
  .vc-focus:hover > :not(:hover) { opacity: 1; }
}
